local germanLocale = locales.deDE
if germanLocale then
    for key, value in pairs(germanNameplateCoverage) do
        local current = rawget(germanLocale, key)
        local englishValue = locales.enUS and rawget(locales.enUS, key)
        if current == nil or current == key or current == englishValue then
            germanLocale[key] = value
        end
    end
end

