for localeKey, entries in pairs(actionBarsTranslations) do
    local locale = locales[localeKey]
    if locale then
        for key, value in pairs(entries) do
            local current = rawget(locale, key)
            local englishValue = locales.enUS and rawget(locales.enUS, key)
            if current == nil or current == key or (localeKey ~= "enUS" and current == englishValue) then
                locale[key] = value
            end
        end
    end
end

