for localeKey, entries in pairs(enhancementsGapTranslations) do
    local locale = locales[localeKey]
    if locale then
        for key, value in pairs(entries) do
            local current = rawget(locale, key)
            local englishValue = locales.enUS and rawget(locales.enUS, key)
            if current == nil or current == key or (localeKey ~= "enUS" and current == englishValue) then
                locale[key] = value
            end
        end
    end
end

-- Latin-American Spanish shares the esES vocabulary unless already translated.
local esMXlocale = locales.esMX
if esMXlocale and locales.esES then
    for key, value in pairs(locales.esES) do
        if rawget(esMXlocale, key) == nil then
            esMXlocale[key] = value
        end
    end
end

-- European Portuguese reuses the ptBR vocabulary unless already translated.
local ptPTlocale = locales.ptPT
if ptPTlocale and locales.ptBR then
    for key, value in pairs(locales.ptBR) do
        if rawget(ptPTlocale, key) == nil then
            ptPTlocale[key] = value
        end
    end
end
